function screenSurfaces(){
  var list = [];
  var mk = "";
  try{ mk = modalKind(); }catch(e){}
  /* ★ 助教自己开着时**不读它自己**（把模型刚说的话再读回去 = 自我循环），
     改读它底下压着的那一层：有内嵌面板就读面板，否则读卡片。 */
  if (mk === "assistant"){
    if (surfaceIsInline()){
      list.push({ tag: "面板:" + SURF_KIND, el: $("inlineBody"), main: true });
      return list;
    }
    list.push({ tag: "卡片", el: $("card"), main: true });
    return list;
  }
